  /* =========================================================
     2. Date, ID, formatting, and safe DOM helpers
     ========================================================= */
  const pad = n => String(n).padStart(2,'0');
  function isoNow(){ return new Date().toISOString(); }
  function relativeIso(days=0,hour=9,minute=0){ const d=new Date(); d.setHours(hour,minute,0,0); d.setDate(d.getDate()+days); return d.toISOString(); }
  function dateInputValue(iso){ if(!iso)return''; const d=new Date(iso); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}`; }
  function dateTimeLocalValue(iso){ if(!iso)return''; const d=new Date(iso); return `${d.getFullYear()}-${pad(d.getMonth()+1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`; }
  function endOfDayIso(dateText){ if(!dateText)return''; return new Date(`${dateText}T23:59:00`).toISOString(); }
  function formatDate(iso,opts={}){ if(!iso)return'—'; const d=new Date(iso); if(Number.isNaN(d.getTime()))return'—'; return new Intl.DateTimeFormat('en-PH',{timeZone:TIMEZONE,month:'short',day:'numeric',year:opts.year===false?undefined:'numeric'}).format(d); }
  function formatDateTime(iso){ if(!iso)return'—'; const d=new Date(iso); if(Number.isNaN(d.getTime()))return'—'; return new Intl.DateTimeFormat('en-PH',{timeZone:TIMEZONE,month:'short',day:'numeric',year:'numeric',hour:'numeric',minute:'2-digit'}).format(d); }
  function money(v){ return Number(v||0).toLocaleString('en-PH',{style:'currency',currency:'PHP'}); }
  function qty(v){ return Number(v||0).toLocaleString('en-PH',{maximumFractionDigits:2}); }
  function normalize(v){ return String(v||'').toLowerCase().replace(/[^a-z0-9.]+/g,' ').replace(/\s+/g,' ').trim(); }
  function esc(v){ return String(v==null?'':v).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c])); }
  function statusLabel(s){ return STATUS_LABELS[s]||String(s||'').replace(/_/g,' ').replace(/\b\w/g,c=>c.toUpperCase()); }
  function statusChip(s,custom){ return `<span class="status ${STATUS_COLOR[s]||'gray'}">${esc(custom||statusLabel(s))}</span>`; }
  function byId(id){ return document.getElementById(id); }
  function setOptions(select,rows,valueKey,labelFn,include){ if(!select)return; const current=select.value; select.innerHTML=(include||'')+rows.map(r=>`<option value="${esc(r[valueKey])}">${esc(labelFn(r))}</option>`).join(''); if([...select.options].some(o=>o.value===current))select.value=current; }
  function debounce(fn,wait=160){ let t; return (...args)=>{clearTimeout(t);t=setTimeout(()=>fn(...args),wait)}; }
  function uid(prefix){ const seq=nextSequence(prefix); return `${prefix}-${seq}`; }
  function nextSequence(prefix){ const all=[]; Object.values(state||{}).forEach(v=>Array.isArray(v)&&v.forEach(x=>{ if(x&&typeof x.id==='string'&&x.id.startsWith(prefix+'-'))all.push(x.id); })); const nums=all.map(id=>Number(id.split('-').pop())).filter(Number.isFinite); return String((nums.length?Math.max(...nums):0)+1).padStart(4,'0'); }
  function yearId(prefix){ return `${prefix}-${new Date().getFullYear()}-${nextSequence(`${prefix}-${new Date().getFullYear()}`)}`; }
  function eventItemId(eventId){ const ev=getEvent(eventId); const series=getSeries(ev?.seriesId); const code=(series?.code||'EVENT').replace(/[^A-Z0-9]/g,'').slice(0,8); const ids=state.deliverables.map(d=>d.eventItemId).filter(Boolean).filter(id=>id.startsWith(`EIT-${code}-`)); const n=ids.map(id=>Number(id.split('-').pop())).filter(Number.isFinite); return `EIT-${code}-${String((n.length?Math.max(...n):0)+1).padStart(4,'0')}`; }
  function safeText(el,text){ if(el)el.textContent=text==null?'':String(text); }
  function downloadJson(data,name){ const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500); }

