  /* =========================================================
     4. State store and persistence
     ========================================================= */
  let state;
  let runtimeExtensions;
  const ui={view:'overview',requestDraftLines:[],editingRequestLineIndex:-1,selectedRequestItemId:'',requestSuggestions:[],requestSuggestionIndex:-1,lendingTab:'FOR_REVIEW',procurementTab:'deliverables',recentDays:7,canvassPage:1,canvassPageSize:8,inventoryPage:1,inventoryPageSize:10,uploads:{restock:null,canvass:null,deliverable:null,release:null},filters:{},renderQueued:false};
  function loadState(){
    try{ const saved=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null'); if(saved&&saved.version==='1.0.0')return saved; }catch(e){ console.warn('Could not read preview storage',e); }
    const seed=createSeedState(); try{localStorage.setItem(STORAGE_KEY,JSON.stringify(seed));}catch(e){} return seed;
  }
  function persist(){ state.updatedAt=isoNow(); if(backendMode!=='mock')return; try{localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}catch(e){toast('Preview changes could not be saved locally. Storage may be full.',true);} }
  function acceptAuthoritativeState(next){state=next;normalizeStateRecords();renderAll();runtimeExtensions?.afterRender();}
  async function commit(message,type='success',mutationResult={}){persist();if(backendMode!=='mock'){try{acceptAuthoritativeState(await services.loadBootstrapData({requestOnly:document.body.classList.contains('request-mode')}));}catch(error){runtimeExtensions?.showRecordedRefreshFailure({correlationId:mutationResult?.correlationId,error});toast(`The action was recorded, but the screen could not refresh.${mutationResult?.correlationId?` Correlation ID: ${mutationResult.correlationId}.`:''}`,true);return false;}}else{renderAll();runtimeExtensions?.afterRender();}if(message)toast(message,type==='error');return true;}
  function resetDemoData(){ if(backendMode!=='mock'){toast('Reset Demo Data is available only in local preview mode.',true);return;}if(!confirm('Reset all local preview changes and restore the original demo scenarios?'))return; try{localStorage.removeItem(STORAGE_KEY);}catch(e){}state=createSeedState();ui.requestDraftLines=[];ui.editingRequestLineIndex=-1;ui.uploads={restock:null,canvass:null,deliverable:null,release:null};persist();renderAll();toast('Demo data restored.'); }
  function audit(action,entityType,entityId,note=''){ state.auditLog.unshift({id:uid('AUD'),action,entityType,entityId,actor:CURRENT_ACTOR.name,at:isoNow(),note}); }
  function appendStatus(record,status,note='',actor=CURRENT_ACTOR.name){ record.status=status;record.updatedAt=isoNow();record.statusHistory=record.statusHistory||[];const h=history(status,record.updatedAt,actor,note);record.statusHistory.push(h);state.statusHistory.push({...h,entityType:record.id.startsWith('LREQ')?'REQUEST':record.id.startsWith('LND')?'LENDING':record.id.startsWith('RL')?'REQUEST_LINE':'RECORD',entityId:record.id}); }

  /* =========================================================
     5. Selectors and derived data
     ========================================================= */
  function getSeries(id){return state.eventSeries.find(x=>x.id===id)}
  function getEvent(id){return state.events.find(x=>x.id===id)}
  function getRequest(id){return state.requests.find(x=>x.id===id)}
  function getLine(id){return state.requestLines.find(x=>x.id===id)}
  function getItem(id){return state.inventoryItems.find(x=>x.id===id)}
  function getDeliverable(id){return state.deliverables.find(x=>x.id===id)}
  function getCanvass(id){return state.canvassReferences.find(x=>x.id===id)}
  function getEvidence(id){return state.evidenceFiles.find(x=>x.id===id)}
  function activeReservationQuantity(itemId){return state.reservations.filter(r=>r.itemId===itemId&&r.status==='ACTIVE').reduce((a,r)=>a+Number(r.quantity||0),0)}
  function itemOnHand(itemId){ const item=getItem(itemId); if(!item)return 0; return Number(item.openingOnHand||0)+state.ledgerTransactions.filter(t=>t.itemId===itemId).reduce((sum,t)=>sum+(t.direction==='IN'?1:-1)*Number(t.quantity||0),0); }
  function availableToPromise(itemId){return Math.max(0,itemOnHand(itemId)-activeReservationQuantity(itemId))}
  function itemAvailabilityStatus(item){if(item.status==='ARCHIVED')return'ARCHIVED';if(item.status==='INACTIVE')return'INACTIVE';if(item.status==='VERIFY')return'VERIFY';const on=itemOnHand(item.id),atp=availableToPromise(item.id);if(on<=0)return'OUT_OF_STOCK';if(atp<=Number(item.reorderThreshold||0))return'LOW_STOCK';return'IN_STOCK';}
  function latestMovement(itemId){return state.ledgerTransactions.filter(t=>t.itemId===itemId).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt))[0]}
  function requestLinesFor(requestId){return state.requestLines.filter(l=>l.requestId===requestId)}
  function deliverableForLine(lineId){return state.deliverables.find(d=>d.requestLineId===lineId)}
  function derivedLendingStatus(t){return t.status==='ON_LOAN'&&t.dueAt&&new Date(t.dueAt)<new Date()?'OVERDUE':t.status}
  function daysSince(iso){return Math.floor((Date.now()-new Date(iso).getTime())/86400000)}
  function eventDisplay(request){ const ev=getEvent(request.eventId),series=getSeries(request.eventSeriesId); if(!ev||!series)return request.displayName||request.id; return `${series.name} — ${ev.name}${request.additionalSequence?` ${request.additionalSequence}`:''}`; }
  function bucketForStatus(s){ if(s==='FOR_CANVASSING')return'FOR_CANVASSING'; if(['WAITING_FOR_BUDGET','TO_BE_PROCURED','PROCURED'].includes(s))return'TO_BE_PROCURED'; if(['READY_TO_RELEASE','PARTIALLY_RELEASED'].includes(s))return'READY_TO_RELEASE'; if(s==='COMPLETED')return'COMPLETED'; return'FOR_REVIEW'; }
  function eventReadiness(eventId){ const lines=state.requestLines.filter(l=>l.eventId===eventId&&!['REJECTED','CANCELLED'].includes(l.status)); const total=lines.length; const counts={FOR_CANVASSING:0,TO_BE_PROCURED:0,READY_TO_RELEASE:0,COMPLETED:0,FOR_REVIEW:0}; lines.forEach(l=>counts[bucketForStatus(l.status)]++); return {lines,total,counts,material:total?Math.round(((counts.READY_TO_RELEASE+counts.COMPLETED)/total)*100):0,completion:total?Math.round((counts.COMPLETED/total)*100):0}; }
  function eventIsCompleted(ev){const r=eventReadiness(ev.id);return ev.status==='COMPLETED'||(r.total>0&&r.counts.COMPLETED===r.total)}
  function activeReleaseRequests(){return state.requests.filter(r=>r.type==='EVENT_LOGISTICS'&&requestLinesFor(r.id).some(l=>['READY_TO_RELEASE','PARTIALLY_RELEASED'].includes(l.status)))}
  function releaseHistoryRequests(){return state.requests.filter(r=>r.type==='EVENT_LOGISTICS'&&requestLinesFor(r.id).length&&requestLinesFor(r.id).every(l=>['COMPLETED','REJECTED','CANCELLED'].includes(l.status)))}
  function currentPage(rows,page,size){ const pages=Math.max(1,Math.ceil(rows.length/size)); const p=Math.min(Math.max(1,page),pages); return {rows:rows.slice((p-1)*size,p*size),page:p,pages,total:rows.length}; }
  function searchItemScore(query,item){ const q=normalize(query); if(!q)return 0; const fields=[item.id,item.name,...(item.aliases||[]),item.category,item.stockArea,item.catalogType,item.handling].map(normalize); if(fields.some(f=>f===q))return 10000;if(fields.some(f=>f.startsWith(q)))return 8000;if(fields.some(f=>f.includes(q)))return 6000;const tokens=q.split(' ');if(tokens.every(t=>fields.some(f=>f.includes(t))))return 4000;return 0; }

