    async saveCanvassReference(payload){let evidence=null;if(payload.file)evidence=await services.uploadEvidenceFile(payload.file,{folderType:'CANVASS_EVIDENCE',relatedId:payload.linkedLineId||'LIBRARY',itemId:'',timestamp:isoNow()});const id=`CAN-${nextSequence('CAN')}`;const supplierId=ensureSupplier(payload.supplierName,payload.location);const rec={id,linkedLineIds:payload.linkedLineId?[payload.linkedLineId]:[],supplierId,supplierName:payload.supplierName,location:payload.location,itemSpec:payload.itemSpec,price:Number(payload.price),unit:payload.unit,receiptStatus:payload.receiptStatus,supplierTin:payload.supplierTin,reliability:payload.reliability,checkedAt:new Date(`${payload.checkedAt}T12:00:00`).toISOString(),notes:payload.notes||'',sourceUrl:payload.sourceUrl||'',evidenceId:evidence?.id||'',status:'ACTIVE',createdAt:isoNow(),updatedAt:isoNow(),createdBy:CURRENT_ACTOR.id,priceHistory:[{price:Number(payload.price),checkedAt:new Date(`${payload.checkedAt}T12:00:00`).toISOString()}]};state.canvassReferences.push(rec);if(payload.linkedLineId){const d=deliverableForLine(payload.linkedLineId);if(d&&!d.linkedCanvassIds.includes(id))d.linkedCanvassIds.push(id);const rr=state.restockRequests.find(r=>r.requestLineId===payload.linkedLineId);if(rr)rr.evidenceStatus='Canvass linked';}audit('SAVE_CANVASS','CANVASS',id,payload.itemSpec);persist();return rec;},
