  function renderOverview(){
    const upcoming=state.events.filter(e=>!eventIsCompleted(e)&&new Date(e.endAt)>=new Date()).sort((a,b)=>new Date(a.startAt)-new Date(b.startAt));
    const activeSeries=new Set(upcoming.map(e=>e.seriesId)).size;const review=state.requests.filter(r=>r.status==='FOR_REVIEW').length;const ready=state.requestLines.filter(l=>['READY_TO_RELEASE','PARTIALLY_RELEASED'].includes(l.status)).length;const overdue=state.lendingTickets.filter(t=>derivedLendingStatus(t)==='OVERDUE').length;const low=state.inventoryItems.filter(i=>['LOW_STOCK','OUT_OF_STOCK','VERIFY'].includes(itemAvailabilityStatus(i))).length;
    byId('heroStats').innerHTML=[['Active event series',activeSeries,'live programs'],['Upcoming sub-events',upcoming.length,'sorted by nearest date'],['Requests needing review',review,'staff action required'],['Ready to release',ready,'controlled handoff'],['Overdue loans',overdue,'follow up now'],['Low-stock items',low,'inventory attention']].map(x=>`<div class="hero-stat"><span>${esc(x[0])}</span><strong>${esc(x[1])}</strong><small>${esc(x[2])}</small></div>`).join('');
    const budget=state.requestLines.filter(l=>l.status==='WAITING_FOR_BUDGET').length;byId('overviewMetrics').innerHTML=[['Open deliverables',state.deliverables.filter(d=>!['COMPLETED','REJECTED','CANCELLED'].includes(d.status)).length,'Across active event requests'],['Waiting for budget',budget,'Budget workflow is visible but not yet automated'],['Open lending tickets',state.lendingTickets.filter(t=>!['RETURNED','COMPLETED','REJECTED','CANCELLED'].includes(t.status)).length,'Includes review, claim, and active loans'],['Evidence records',state.evidenceFiles.length,'Mock Drive metadata retained']].map(x=>`<article class="card metric"><span>${esc(x[0])}</span><strong>${esc(x[1])}</strong><small>${esc(x[2])}</small></article>`).join('');
    safeText(byId('upcomingCount'),`${upcoming.length} upcoming`);renderUpcomingEvents(upcoming);renderPulse();renderCompletedEvents();renderRoadmap();
  }
  function renderUpcomingEvents(upcoming){
    const grouped={};upcoming.forEach(e=>(grouped[e.seriesId]||(grouped[e.seriesId]=[])).push(e));
    byId('upcomingEvents').innerHTML=Object.entries(grouped).map(([seriesId,events])=>{const s=getSeries(seriesId);return `<article class="panel series-card"><div class="series-header"><div><h3>${esc(s?.name||seriesId)}</h3><p>${events.length} upcoming sub-event${events.length===1?'':'s'} · Stable code ${esc(s?.code||'—')}</p></div><span class="pill">${esc(s?.status||'ACTIVE')}</span></div><div class="subevents">${events.map(renderSubevent).join('')}</div></article>`}).join('')||'<div class="empty">No upcoming events in demo data.</div>';
  }
  function renderSubevent(ev){
    const r=eventReadiness(ev.id);const badges=[];if(r.lines.some(l=>l.status==='WAITING_FOR_BUDGET'))badges.push(statusChip('WAITING_FOR_BUDGET'));if(r.lines.some(l=>l.status==='FOR_REVIEW'))badges.push(statusChip('FOR_REVIEW'));if(new Date(ev.startAt)<new Date()&&!eventIsCompleted(ev))badges.push(statusChip('OVERDUE'));if(r.lines.some(l=>l.status==='REJECTED'))badges.push(statusChip('REJECTED','Blocked'));
    return `<div class="subevent"><div class="subevent-main"><div><h4>${esc(ev.name)}</h4><div class="subevent-meta">${esc(formatDateTime(ev.startAt))} – ${esc(formatDateTime(ev.endAt))}<br>${esc(ev.owner)} · ${esc(ev.venue||'Venue pending')}</div><div class="button-row" style="margin-top:7px">${badges.join('')}</div></div><div class="bucket-grid"><div class="bucket"><b>${r.counts.FOR_CANVASSING}</b><span>For Canvassing</span></div><div class="bucket"><b>${r.counts.TO_BE_PROCURED}</b><span>To Be Procured</span></div><div class="bucket"><b>${r.counts.READY_TO_RELEASE}</b><span>Ready to Release</span></div><div class="bucket"><b>${r.counts.COMPLETED}</b><span>Completed</span></div></div><div class="progress-pair"><div><div class="progress-label"><span>Material readiness</span><b>${r.material}%</b></div><div class="track"><i style="width:${r.material}%"></i></div></div><div><div class="progress-label"><span>Completion</span><b>${r.completion}%</b></div><div class="track complete"><i style="width:${r.completion}%"></i></div></div></div></div><div class="subevent-actions"><button class="link-button" data-filter-proc-event="${esc(ev.id)}">Open deliverables →</button><button class="link-button" data-filter-release-event="${esc(ev.id)}">Open release tickets →</button></div><details class="item-details"><summary>View ${r.total} requested line${r.total===1?'':'s'}</summary><div class="detail-lines">${r.lines.map(l=>`<div class="detail-line"><div><strong>${esc(l.description)}</strong><small>${qty(l.quantity)} ${esc(l.unit)} · ${esc(l.fulfillmentSource.replace(/_/g,' '))}</small></div>${statusChip(l.status)}</div>`).join('')||'<div class="empty">No request lines.</div>'}</div></details></div>`;
  }
  function renderPulse(){
    const alerts=[];const review=state.requests.filter(r=>r.status==='FOR_REVIEW');if(review.length)alerts.push({dot:'',title:`${review.length} request${review.length===1?'':'s'} awaiting review`,detail:'Accept or reject before reserving stock or moving into procurement.',view:'procurement'});
    const budget=state.requestLines.filter(l=>l.status==='WAITING_FOR_BUDGET');if(budget.length)alerts.push({dot:'',title:`${budget.length} line${budget.length===1?'':'s'} waiting for budget`,detail:'Preferred quotes are ready for the future DOF approval workflow.',view:'procurement'});
    const overdue=state.lendingTickets.filter(t=>derivedLendingStatus(t)==='OVERDUE');if(overdue.length)alerts.push({dot:'red',title:`${overdue.length} overdue loan${overdue.length===1?'':'s'}`,detail:`Oldest due ${formatDateTime(overdue.sort((a,b)=>new Date(a.dueAt)-new Date(b.dueAt))[0].dueAt)}.`,view:'lending'});
    const low=state.inventoryItems.filter(i=>['LOW_STOCK','OUT_OF_STOCK','VERIFY'].includes(itemAvailabilityStatus(i)));if(low.length)alerts.push({dot:'red',title:`${low.length} inventory exception${low.length===1?'':'s'}`,detail:'Low, out-of-stock, or verification-blocked items need attention.',view:'inventory'});
    const missing=state.restockRequests.filter(r=>r.evidenceStatus==='Missing');if(missing.length)alerts.push({dot:'',title:`${missing.length} restock request${missing.length===1?'':'s'} missing evidence`,detail:'Attach a canvass or receipt when the workflow reaches receiving.',view:'restocking'});
    const partial=state.requestLines.filter(l=>l.status==='PARTIALLY_RELEASED');if(partial.length)alerts.push({dot:'',title:`${partial.length} partially released line${partial.length===1?'':'s'}`,detail:'Remaining quantities still need recipient confirmation.',view:'release'});
    byId('operationalPulse').innerHTML=alerts.map(a=>`<button class="alert" type="button" data-go="${a.view}"><span class="alert-dot ${a.dot}"></span><span><strong>${esc(a.title)}</strong><small>${esc(a.detail)}</small></span><span class="pill">Open</span></button>`).join('')||'<div class="empty">No actionable exceptions.</div>';
  }
  function renderCompletedEvents(){const events=state.events.filter(eventIsCompleted).sort((a,b)=>new Date(b.endAt)-new Date(a.endAt));safeText(byId('completedEventCount'),`${events.length} event${events.length===1?'':'s'}`);byId('completedEvents').innerHTML=events.map(e=>{const r=eventReadiness(e.id);return `<details class="item-details"><summary>${esc(getSeries(e.seriesId)?.name||'Event')} — ${esc(e.name)}</summary><div class="detail-lines"><div class="detail-line"><div><strong>${esc(formatDateTime(e.startAt))}</strong><small>${r.counts.COMPLETED}/${r.total} lines completed · ${esc(e.owner)}</small></div>${statusChip('COMPLETED')}</div></div></details>`}).join('')||'<div class="empty">No completed events.</div>'}
