  function filterRequestSuggestionsForCatalog(){handleRequestItemInput()}
  function handleRequestItemInput(){const q=byId('requestItemInput').value.trim();if(!q){hideRequestSuggestions();ui.selectedRequestItemId='';showNewItemMode(false);updateRequestDecision();return}ui.requestSuggestions=requestCatalog().map(i=>({i,score:searchItemScore(q,i)})).filter(x=>x.score>0).sort((a,b)=>b.score-a.score||a.i.name.localeCompare(b.i.name)).slice(0,8).map(x=>x.i);ui.requestSuggestionIndex=-1;const box=byId('requestAutocomplete');if(!ui.requestSuggestions.length){box.innerHTML=`<button type="button" class="suggestion" data-new-unlisted="1"><strong>New / Unlisted Item</strong><code>No catalog match</code><span class="stock"><b>For Canvassing</b>Specification required</span></button>`;box.querySelector('[data-new-unlisted]').onclick=()=>selectNewUnlistedItem();}else box.innerHTML=ui.requestSuggestions.map((i,index)=>`<button id="request-suggestion-${index}" type="button" class="suggestion" role="option" aria-selected="false" data-item-suggestion="${esc(i.id)}"><strong>${esc(i.name)}</strong><code>${esc(i.id)} · ${esc(i.stockArea)} · ${esc(i.handling)} · ${esc(i.unit)}</code><span class="stock"><b>${qty(availableToPromise(i.id))} ${esc(i.unit)}</b>${esc(statusLabel(itemAvailabilityStatus(i)))}</span></button>`).join('');box.classList.add('show');byId('requestItemInput').setAttribute('aria-expanded','true');ui.selectedRequestItemId='';showNewItemMode(false);updateRequestDecision()}
  function handleRequestAutocompleteKeys(e){const box=byId('requestAutocomplete');if(!box.classList.contains('show'))return;if(e.key==='Escape'){e.preventDefault();hideRequestSuggestions();return}if(!ui.requestSuggestions.length)return;if(e.key==='ArrowDown'){e.preventDefault();ui.requestSuggestionIndex=Math.min(ui.requestSuggestions.length-1,ui.requestSuggestionIndex+1);updateRequestSuggestionActive()}else if(e.key==='ArrowUp'){e.preventDefault();ui.requestSuggestionIndex=Math.max(0,ui.requestSuggestionIndex-1);updateRequestSuggestionActive()}else if(e.key==='Enter'&&ui.requestSuggestionIndex>=0){e.preventDefault();selectRequestItem(ui.requestSuggestions[ui.requestSuggestionIndex].id)}}
